<script setup lang="ts">
import {ref,watch} from 'vue';import {useRouter} from 'vue-router';import FuturePanels from './FuturePanels.vue';import Icon from '../../shared/Icon.vue';
import type {components} from '../../shared/api/generated';
const props=withDefaults(defineProps<{items:components['schemas']['MeetingItem'][];owned?:boolean;categories?:Record<string,string>}>(),{owned:true,categories:()=>({})});const router=useRouter(),selected=ref<string[]>([]),panels=ref<InstanceType<typeof FuturePanels>>();watch(()=>props.items,()=>selected.value=[]);function all(checked:boolean){selected.value=checked?props.items.map(x=>x.id):[];}async function copy(id:string){try{await navigator.clipboard.writeText(id);}catch{/* The identifier stays visible and selectable. */}}
const labels:Record<components['schemas']['MeetingItem']['stage'],string>={ENTRY:'会议采集',TRANSCRIPT_PENDING:'转写待处理',TRANSCRIPT_FAILED:'转写失败',MINUTES_PENDING:'纪要待处理',MINUTES_FAILED:'纪要生成失败',READY_TO_PUBLISH:'待发布',PUBLISH_FAILED:'发布失败',PUBLISHED:'已发布'};
function stage(m:components['schemas']['MeetingItem']){return m.workspaceStage??m.stage;}
function tone(m:components['schemas']['MeetingItem']){const s=stage(m);return s.endsWith('FAILED')?'red':s==='PUBLISHED'?'green':s==='ENTRY'?'gray':s==='READY_TO_PUBLISH'?'amber':'blue';}
function updated(value:string|null|undefined){if(!value)return '--';const date=new Date(value);if(!Number.isFinite(+date))return '--';const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date);const get=(k:string)=>parts.find(p=>p.type===k)!.value;return `${get('year')}/${get('month')}/${get('day')} ${get('hour')}:${get('minute')}:${get('second')}`;}
</script>
<template>
 <div v-if="owned&&selected.length" class="banner info mb12">已选 {{selected.length}} 场会议<span class="ml-a"></span><button class="btn sm" @click="panels?.open('assign',`已选择 ${selected.length} 场会议`)">批量调整专题</button><button class="btn sm ghost" @click="selected=[]">取消选择</button></div>
 <div class="table-wrap"><table class="tbl m19-table" aria-label="当前范围的会议"><thead><tr><th v-if="owned"><input type="checkbox" :checked="!!items.length&&selected.length===items.length" aria-label="全选当前页" @change="all(($event.target as HTMLInputElement).checked)"/></th><th>会议</th><th>会议分类</th><th v-if="!owned">会议负责人</th><th>参会人</th><th>当前状态</th><th>会议日期</th><th>时长</th><th v-if="owned">专题</th><th>更新时间</th><th>发布知识库</th><th v-if="owned">操作</th></tr></thead><tbody>
  <tr v-for="meeting in items" :key="meeting.id"><td v-if="owned"><input v-model="selected" :value="meeting.id" type="checkbox" :aria-label="'选择会议 '+(meeting.name??'未命名会议')"/></td><td><button class="m19-name" @click="router.push(`/meeting/${meeting.id}`)">{{meeting.name??'未命名会议'}}</button><div class="small muted mono flex" style="gap:5px">{{meeting.id}}<button class="btn sm ghost m19-copy" title="复制编号" :aria-label="'复制编号 '+meeting.id" @click="copy(meeting.id)"><Icon name="copy" :size="12"/></button></div></td><td>{{meeting.category?(categories[meeting.category]??meeting.category):'其他'}}</td><td v-if="!owned">--</td><td><span class="m19-people" :tabindex="(meeting.participants?.length??0)>3?0:undefined" :title="meeting.participants?.join('、')??''">{{meeting.participants?.slice(0,3).join('、')||'--'}}<template v-if="(meeting.participants?.length??0)>3"> 等{{meeting.participants!.length}}人<span class="m19-people-tip" role="tooltip">{{meeting.participants!.join('、')}}</span></template></span></td><td><span class="tag" :class="tone(meeting)">{{labels[stage(meeting)]}}</span></td><td>{{meeting.occurredOn??'--'}}</td><td class="num">--</td><td v-if="owned"><button class="m19-topic-name" title="未归入专题" aria-label="调整专题：未归入专题" @click="panels?.open('assign',meeting.name??meeting.id)"><span>未归入专题</span><Icon name="edit" :size="11"/></button></td><td class="small num m19-updated-time">{{updated(meeting.updatedAt)}}</td><td class="small m19-path" title="--">--</td><td v-if="owned"><div class="flex wrap"><button class="btn sm danger" :disabled="meeting.stage==='PUBLISHED'" :title="meeting.stage==='PUBLISHED'?'录音中、发布中或曾发布的会议不可删除':undefined" @click="panels?.open('delete',meeting.name??meeting.id)">删除</button><button v-if="stage(meeting)==='TRANSCRIPT_FAILED'||stage(meeting)==='MINUTES_FAILED'" class="btn sm danger" @click="router.push(`/meeting/${meeting.id}`)">{{stage(meeting)==='TRANSCRIPT_FAILED'?'重试转写':'重试纪要'}}</button><button v-if="stage(meeting)==='PUBLISH_FAILED'" class="btn sm primary" @click="router.push(`/meeting/${meeting.id}/publish`)">重试发布</button></div></td></tr>
  <tr v-if="!items.length"><td :colspan="owned?11:9"><div class="empty"><Icon name="search" :size="32"/><div class="e-t">没有符合条件的会议</div><div class="e-d">请调整或清空筛选条件</div></div></td></tr>
 </tbody></table></div><FuturePanels ref="panels"/>
</template>
